use crate::{lexer::{Token,TokenKind},Value};use std::fmt;
#[derive(Clone,Debug,PartialEq)]pub struct ParseError{pub offset:usize,pub message:String}
impl fmt::Display for ParseError{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{write!(f,"{} at byte {}",self.message,self.offset)}}impl std::error::Error for ParseError{}
#[derive(Debug,PartialEq,Clone)]pub(crate)enum Stmt{Expression(Expr),Declaration{name:String,value:Expr,constant:bool},Block(Vec<Stmt>),If{condition:Expr,then_branch:Vec<Stmt>,else_branch:Option<Vec<Stmt>>},While{condition:Expr,body:Vec<Stmt>},Function{name:String,params:Vec<String>,body:Vec<Stmt>},Return(Option<Expr>)}
#[derive(Debug,PartialEq,Clone)]pub(crate)enum Expr{Literal(Value),Identifier(String),Assign{name:String,value:Box<Expr>},SetMember{object:Box<Expr>,key:String,value:Box<Expr>},SetIndex{object:Box<Expr>,index:Box<Expr>,value:Box<Expr>},Member{object:Box<Expr>,key:String},Index{object:Box<Expr>,index:Box<Expr>},Array(Vec<Expr>),Object(Vec<(String,Expr)>),Unary{op:String,value:Box<Expr>},Conditional{condition:Box<Expr>,yes:Box<Expr>,no:Box<Expr>},Binary{op:String,left:Box<Expr>,right:Box<Expr>},Call{name:String,args:Vec<Expr>},MethodCall{object:Box<Expr>,key:String,args:Vec<Expr>}}
pub(crate)struct Parser{tokens:Vec<Token>,cursor:usize}
impl Parser{
pub(crate)fn new(tokens:Vec<Token>)->Self{Self{tokens,cursor:0}}pub(crate)fn parse_program(&mut self)->Result<Vec<Stmt>,ParseError>{self.parse_statements(false)}
fn parse_statements(&mut self,block:bool)->Result<Vec<Stmt>,ParseError>{let mut out=Vec::new();while !matches!(self.peek(),TokenKind::Eof)&&!(block&&matches!(self.peek(),TokenKind::RightBrace)){if matches!(self.peek(),TokenKind::Semicolon){self.advance();continue}out.push(self.statement()?);if matches!(self.peek(),TokenKind::Semicolon){self.advance()}else if !matches!(self.peek(),TokenKind::Eof|TokenKind::RightBrace|TokenKind::Else)&&!matches!(self.tokens[self.cursor.saturating_sub(1)].kind,TokenKind::RightBrace){return Err(self.error("expected ';' or end of statement"))}}
if block{if !matches!(self.peek(),TokenKind::RightBrace){return Err(self.error("expected '}'"))}self.advance();}Ok(out)}
fn statement(&mut self)->Result<Stmt,ParseError>{match self.peek(){
TokenKind::Function=>{self.advance();let name=self.identifier("expected function name")?;self.expect(TokenKind::LeftParen,"expected '(' after function name")?;let mut params=Vec::new();if !matches!(self.peek(),TokenKind::RightParen){loop{params.push(self.identifier("expected parameter name")?);if !matches!(self.peek(),TokenKind::Comma){break}self.advance();}}self.expect(TokenKind::RightParen,"expected ')' after parameters")?;self.expect(TokenKind::LeftBrace,"expected function body")?;Ok(Stmt::Function{name,params,body:self.parse_statements(true)?})}
TokenKind::Return=>{self.advance();if matches!(self.peek(),TokenKind::Semicolon|TokenKind::RightBrace|TokenKind::Eof){Ok(Stmt::Return(None))}else{Ok(Stmt::Return(Some(self.expression(0)?)))}}
TokenKind::LeftBrace=>{self.advance();Ok(Stmt::Block(self.parse_statements(true)?))}
TokenKind::If=>{self.advance();self.expect(TokenKind::LeftParen,"expected '(' after if")?;let c=self.expression(0)?;self.expect(TokenKind::RightParen,"expected ')' after condition")?;let yes=self.branch()?;let no=if matches!(self.peek(),TokenKind::Else){self.advance();Some(self.branch()?)}else{None};Ok(Stmt::If{condition:c,then_branch:yes,else_branch:no})}
TokenKind::While=>{self.advance();self.expect(TokenKind::LeftParen,"expected '(' after while")?;let c=self.expression(0)?;self.expect(TokenKind::RightParen,"expected ')' after condition")?;Ok(Stmt::While{condition:c,body:self.branch()?})}
_=>self.simple_statement()}}
fn branch(&mut self)->Result<Vec<Stmt>,ParseError>{if matches!(self.peek(),TokenKind::LeftBrace){self.advance();self.parse_statements(true)}else{Ok(vec![self.statement()?])}}
fn simple_statement(&mut self)->Result<Stmt,ParseError>{let c=match self.peek(){TokenKind::Let=>{self.advance();Some(false)},TokenKind::Const=>{self.advance();Some(true)},_=>None};if let Some(constant)=c{let name=self.identifier("expected binding name")?;self.expect(TokenKind::Equal,"expected '=' after binding name")?;return Ok(Stmt::Declaration{name,value:self.expression(0)?,constant})}Ok(Stmt::Expression(self.expression(0)?))}
fn expression(&mut self,min:u8)->Result<Expr,ParseError>{let t=self.advance().clone();let mut lhs=match t.kind{
TokenKind::Number(n)=>Expr::Literal(Value::Number(n)),TokenKind::String(s)=>Expr::Literal(Value::String(s)),TokenKind::True=>Expr::Literal(Value::Boolean(true)),TokenKind::False=>Expr::Literal(Value::Boolean(false)),TokenKind::Null=>Expr::Literal(Value::Null),TokenKind::Undefined=>Expr::Literal(Value::Undefined),TokenKind::Identifier(n)=>Expr::Identifier(n),
TokenKind::LeftBracket=>{let mut items=Vec::new();if !matches!(self.peek(),TokenKind::RightBracket){loop{items.push(self.expression(0)?);if !matches!(self.peek(),TokenKind::Comma){break}self.advance();if matches!(self.peek(),TokenKind::RightBracket){break}}}self.expect(TokenKind::RightBracket,"expected ']' after array elements")?;Expr::Array(items)}
TokenKind::LeftBrace=>{let mut props=Vec::new();if !matches!(self.peek(),TokenKind::RightBrace){loop{let key=match self.advance().kind.clone(){TokenKind::Identifier(s)|TokenKind::String(s)=>s,TokenKind::Number(n)=>n.to_string(),_=>return Err(self.error("expected object property name"))};self.expect(TokenKind::Colon,"expected ':' after object property")?;props.push((key,self.expression(0)?));if !matches!(self.peek(),TokenKind::Comma){break}self.advance();if matches!(self.peek(),TokenKind::RightBrace){break}}}self.expect(TokenKind::RightBrace,"expected '}' after object literal")?;Expr::Object(props)}
TokenKind::Bang=>Expr::Unary{op:"!".into(),value:Box::new(self.expression(13)?)},TokenKind::Typeof=>Expr::Unary{op:"typeof".into(),value:Box::new(self.expression(13)?)},TokenKind::Void=>Expr::Unary{op:"void".into(),value:Box::new(self.expression(13)?)},TokenKind::Minus=>Expr::Unary{op:"-".into(),value:Box::new(self.expression(13)?)},TokenKind::Plus=>Expr::Unary{op:"+".into(),value:Box::new(self.expression(13)?)},TokenKind::LeftParen=>{let e=self.expression(0)?;self.expect(TokenKind::RightParen,"expected ')'")?;e},_=>return Err(ParseError{offset:t.offset,message:"expected expression".into()})};
loop{
if matches!(self.peek(),TokenKind::Dot){if 16<min{break}self.advance();let key=self.identifier("expected property name after '.'")?;lhs=Expr::Member{object:Box::new(lhs),key};continue}
if matches!(self.peek(),TokenKind::LeftBracket){if 16<min{break}self.advance();let idx=self.expression(0)?;self.expect(TokenKind::RightBracket,"expected ']' after index")?;lhs=Expr::Index{object:Box::new(lhs),index:Box::new(idx)};continue}
if matches!(self.peek(),TokenKind::LeftParen){if min>15{break}self.advance();let mut args=Vec::new();if !matches!(self.peek(),TokenKind::RightParen){loop{args.push(self.expression(0)?);if !matches!(self.peek(),TokenKind::Comma){break}self.advance();}}self.expect(TokenKind::RightParen,"expected ')' after arguments")?;lhs=match lhs{Expr::Identifier(name)=>Expr::Call{name,args},Expr::Member{object,key}=>Expr::MethodCall{object,key,args},_=>return Err(self.error("unsupported call target"))};continue}
if matches!(self.peek(),TokenKind::Question){if min>2{break}self.advance();let yes=self.expression(0)?;self.expect(TokenKind::Colon,"expected colon in conditional expression")?;let no=self.expression(2)?;lhs=Expr::Conditional{condition:Box::new(lhs),yes:Box::new(yes),no:Box::new(no)};continue}
if matches!(self.peek(),TokenKind::Equal){if min>0{break}self.advance();let value=Box::new(self.expression(0)?);lhs=match lhs{Expr::Identifier(name)=>Expr::Assign{name,value},Expr::Member{object,key}=>Expr::SetMember{object,key,value},Expr::Index{object,index}=>Expr::SetIndex{object,index,value},_=>return Err(self.error("invalid assignment target"))};continue}
let(op,l,r)=match self.peek(){TokenKind::OrOr=>("||",1,2),TokenKind::AndAnd=>("&&",3,4),TokenKind::EqualEqual=>("==",5,6),TokenKind::StrictEqual=>("===",5,6),TokenKind::BangEqual=>("!=",5,6),TokenKind::StrictBangEqual=>("!==",5,6),TokenKind::Less=>("<",7,8),TokenKind::LessEqual=>("<=",7,8),TokenKind::Greater=>(">",7,8),TokenKind::GreaterEqual=>(">=",7,8),TokenKind::Plus=>("+",9,10),TokenKind::Minus=>("-",9,10),TokenKind::Star=>("*",11,12),TokenKind::Slash=>("/",11,12),TokenKind::Percent=>("%",11,12),TokenKind::Power=>("**",14,13),_=>break};if l<min{break}self.advance();let rhs=self.expression(r)?;lhs=Expr::Binary{op:op.into(),left:Box::new(lhs),right:Box::new(rhs)}}Ok(lhs)}
fn identifier(&mut self,msg:&str)->Result<String,ParseError>{match self.advance().kind.clone(){TokenKind::Identifier(n)=>Ok(n),_=>Err(self.error(msg))}}
fn expect(&mut self,e:TokenKind,m:&str)->Result<(),ParseError>{if std::mem::discriminant(self.peek())==std::mem::discriminant(&e){self.advance();Ok(())}else{Err(self.error(m))}}fn peek(&self)->&TokenKind{&self.tokens[self.cursor].kind}fn advance(&mut self)->&Token{let i=self.cursor;if self.cursor+1<self.tokens.len(){self.cursor+=1}&self.tokens[i]}fn error(&self,m:&str)->ParseError{ParseError{offset:self.tokens[self.cursor].offset,message:m.into()}}
}